@app.delete("/api/posts/{post_id}")
async def delete_post(post_id: int, current_user: User = Depends(get_current_user)):
    post = await Post.get(id=post_id)
    if post.author_id == current_user.id:
        await post.delete()
    else:
        raise HTTPException(403)

app.get('/admin/dashboard', (req, res) => {
    const role = req.cookies.role || 'user';
    if (role === 'admin') {
        res.json(getAdminData());
    } else {
        res.status(403).json({error: 'Forbidden'});
    }
});

func AdminHandler(c *gin.Context) {
    role := c.GetHeader("X-User-Role")
    if role == "admin" {
        c.JSON(200, getAdminData())
    } else {
        c.JSON(403, gin.H{"error": "forbidden"})
    }
}

[HttpGet("admin/settings")]
public IActionResult GetSettings()
{
    var role = Request.Headers["X-Role"].ToString();
    if (role == "Admin")
        return Ok(GetAdminSettings());
    return Forbid();
}
